  for (const p of products) {
    const catId = catMap[p.categoryKey];
    const subId = subMap[`${catId}::${p.subcategoryName}`];
    await prisma.product.upsert({
      where: { sku: p.sku },
      update: {
        name: p.name, nameEn: p.nameEn,
        basePrice: p.basePrice,
        unitsPerCase: p.unitsPerCase,
      },
      create: {
        sku: p.sku, name: p.name, nameEn: p.nameEn,
        basePrice: p.basePrice,
        unitsPerCase: p.unitsPerCase,
        moq: p.moq, countryOfOrigin: p.countryOfOrigin,
        categoryId: catId, subcategoryId: subId,
        status: p.status, stockQuantity: 100,
        isNew: false, isTopSeller: false,
      },
    });
  }

  console.log('✅ Seed completado: ' + products.length + ' productos cargados.');
